package com.meridian.substrate.common.domain;

import com.fasterxml.jackson.databind.JsonNode;
import com.meridian.substrate.common.domain.enums.CapabilityStatus;
import jakarta.persistence.*;

import java.util.UUID;

/**
 * A Capability is a named business capability within a Domain — authored by
 * the customer or generated by AI in Phase 2's Capability Designer. Capabilities
 * form a tree (parentCapabilityId) and carry both a stable internal `name` and
 * a mutable customer-facing `displayName` (see {@link CapabilityNameHistory}).
 */
@Entity
@Table(name = "capabilities")
public class Capability extends BaseEntity {

    @Column(name = "domain_id", nullable = false)
    private UUID domainId;

    @Column(name = "parent_capability_id")
    private UUID parentCapabilityId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "display_name", nullable = false)
    private String displayName;

    @Column(name = "description", columnDefinition = "TEXT")
    private String description;

    @Column(name = "level", nullable = false)
    private int level;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 50)
    private CapabilityStatus status = CapabilityStatus.DRAFT;

    @Column(name = "source_pack_id")
    private UUID sourcePackId;

    @Column(name = "ai_generated", nullable = false)
    private boolean aiGenerated;

    @Convert(converter = JsonNodeConverter.class)
    @Column(name = "metadata", columnDefinition = "TEXT")
    private JsonNode metadata;

    /**
     * 0-based ordinal within the sibling group (same {@code domainId} +
     * {@code parentCapabilityId}). Re-written as a contiguous sequence by
     * {@code CapabilityService.reorder}; the {@code capability_designer}
     * tree sorts children by this column when building its hierarchy.
     */
    @Column(name = "sequence_order", nullable = false)
    private int sequenceOrder;

    public UUID getDomainId() { return domainId; }
    public void setDomainId(UUID domainId) { this.domainId = domainId; }

    public UUID getParentCapabilityId() { return parentCapabilityId; }
    public void setParentCapabilityId(UUID parentCapabilityId) { this.parentCapabilityId = parentCapabilityId; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getDisplayName() { return displayName; }
    public void setDisplayName(String displayName) { this.displayName = displayName; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public int getLevel() { return level; }
    public void setLevel(int level) { this.level = level; }

    public CapabilityStatus getStatus() { return status; }
    public void setStatus(CapabilityStatus status) { this.status = status; }

    public UUID getSourcePackId() { return sourcePackId; }
    public void setSourcePackId(UUID sourcePackId) { this.sourcePackId = sourcePackId; }

    public boolean isAiGenerated() { return aiGenerated; }
    public void setAiGenerated(boolean aiGenerated) { this.aiGenerated = aiGenerated; }

    public JsonNode getMetadata() { return metadata; }
    public void setMetadata(JsonNode metadata) { this.metadata = metadata; }

    public int getSequenceOrder() { return sequenceOrder; }
    public void setSequenceOrder(int sequenceOrder) { this.sequenceOrder = sequenceOrder; }
}
